def generate_and_save():
    output_path = os.path.join(os.path.dirname(os.path.dirname(__file__)), "data", "players.json")
    for player in PLAYERS_DATA:
        if not player.get("image_url"):
            clean_name = player["name"].replace(" ", "_").lower()
            player["image_url"] = f"https://api.dicebear.com/7.x/bottts/svg?seed={clean_name}&backgroundColor=071a36"

        is_uncapped = player.get("is_uncapped", False)
        rating = player.get("rating", 80)
        role = player.get("role", "Batsman")

        if not is_uncapped and rating >= 93:
            pool = "Marquee"
            is_marquee = True
        elif is_uncapped:
            pool = "Uncapped"
            is_marquee = False
        else:
            pool = "Capped"
            is_marquee = False

        plural = "Batsmen" if role == "Batsman" else ("Bowlers" if role == "Bowler" else ("All-rounders" if role == "All-rounder" else "Wicketkeepers"))
        player["pool"] = pool
        player["is_marquee"] = is_marquee
        player["set_name"] = f"{pool} {plural}"

    with open(output_path, "w", encoding="utf-8") as f:
        json.dump(PLAYERS_DATA, f, indent=2)

    print(f"Generated {len(PLAYERS_DATA)} players in {output_path}")

if __name__ == "__main__":
    generate_and_save()

